import { carousel } from "@zuccadev-labs/zuix-zui/dom";

const projects = document.querySelector("#projects");
projects.addEventListener("z:change", (event) => console.debug("slide", event.detail.index));
// carousel(projects).next();   // también prev(), goTo(index) y destroy()

import { carousel } from "@zuccadev-labs/zuix-zui/dom";

// Cada <canvas data-raster> es a la vez el slide y la textura de las zonas curvas. Se pinta con los tokens activos.
const covers = document.querySelector("#covers");
const token = (name) => getComputedStyle(covers).getPropertyValue(name).trim();
covers.querySelectorAll("canvas[data-raster]").forEach((canvas, index) => {
  const ctx = canvas.getContext("2d");
  // Fondo opaco: la textura debe verse igual que el slide sobre cualquier fondo.
  ctx.fillStyle = token("--z-reading-bg");
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = token("--z-accent");
  for (let bar = 0; bar < 6; bar++) {
    const height = 60 + (((bar + 1) * (index + 3) * 37) % 170);
    ctx.globalAlpha = 0.2 + ((bar + index) % 4) * 0.15;
    ctx.fillRect(40 + bar * 96, canvas.height - 48 - height, 64, height);
  }
  ctx.globalAlpha = 1;
  ctx.fillStyle = token("--z-fg");
  ctx.font = `700 56px ${token("--z-font-sans") || "sans-serif"}`;
  ctx.textBaseline = "top";
  ctx.fillText(canvas.getAttribute("aria-label"), 40, 36);
});
// Los lienzos se han pintado después de activar el carrusel: refresh() rehace las réplicas y las texturas.
carousel(covers).refresh();
// Con contenido HTML en los slides, la imagen se declara aparte: data-raster="#id", data-raster-src="url"
// o carousel(el, { rasterize: (slide, index, size) => imagen }).

import { setCalendarOptions } from "@zuccadev-labs/zuix-zui/dom";
setCalendarOptions(document.querySelector("#price-calendar"), {
  dayContent: (date) => (date.endsWith("0") ? "$89" : null),
  dayDescription: (date) => (date.endsWith("0") ? "from $89" : null),
});

import { setComboboxLoading, setComboboxOptions } from "@zuccadev-labs/zuix-zui/dom";

const repo = document.querySelector("#repo");
repo.addEventListener("z:input", async (event) => {
  setComboboxLoading(repo, true);
  const found = await searchRepositories(event.detail.value);
  setComboboxOptions(repo, found.map((item) => ({ value: item.id, label: item.name, icon: "folder" })));
  setComboboxLoading(repo, false);
});

import { toast } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#commands").addEventListener("z:select", (event) => {
  toast({ title: "Command: " + event.detail.value });
});

import { confirm } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#delete").addEventListener("click", async () => {
  const ok = await confirm({ title: "Delete project?", description: "This cannot be undone.", intent: "danger", confirmLabel: "Delete" });
  if (ok) removeProject();
});

import { toast } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#save").addEventListener("click", () => {
  toast({ title: "Changes saved", description: "Your profile is up to date.", intent: "success" });
});

import { toastPromise } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#deploy").addEventListener("click", () => {
  const job = new Promise((resolve) => setTimeout(() => resolve("v0.3.0"), 1500));
  toastPromise(job, {
    loading: "Deploying…",
    success: (version) => ({ title: "Deployed", description: `Version ${version} is live.` }),
    error: "Deploy failed",
  });
});

import { startTour } from "@zuccadev-labs/zuix-zui/dom";

document.querySelector("#tour-start").addEventListener("click", () => {
  startTour({
    steps: [
      { target: "#tour-start", title: "Create a project", content: "Projects group your files and members." },
      { title: "You are ready", content: "You can restart this tour from Help." },
    ],
  });
});
